-- These functions are granted only to the private fixture/controller roles.
CREATE FUNCTION c1_api.fixture_init(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE st jsonb;t jsonb;id jsonb;g jsonb;BEGIN
 IF EXISTS(SELECT 1 FROM c1_private.deployment WHERE ns=n) THEN PERFORM c1_private.fail('ALREADY_INITIALIZED');END IF;
 INSERT INTO c1_private.deployment(ns,manifest,now,clock_floor,heartbeat,halt,reason) VALUES(n,q->'manifest',(q->>'now')::bigint,(q->>'now')::bigint,(q->>'now')::bigint,false,'LOCAL_SYNTHETIC');INSERT INTO c1_private.transaction_guard(ns) VALUES(n);
 FOR st IN SELECT value FROM jsonb_array_elements(q->'stores') LOOP INSERT INTO c1_private.stores(ns,store) VALUES(n,st->>'id');INSERT INTO c1_private.rollups VALUES(n,st->>'id','{"F":"0","A":"0","R":"0","H":"0","S":"0","X":"0","counts":{"F":0,"A":0,"R":0,"H":0,"S":0,"X":0}}');END LOOP;
 FOR id IN SELECT value FROM jsonb_array_elements(q->'identities') LOOP INSERT INTO c1_private.identities(ns,subject,canonical_email,email_key) VALUES(n,id->>'subject',id->>'canonical_email',c1_private.h(id->>'email_key'));IF id ? 'payer' THEN INSERT INTO c1_private.payer_bindings VALUES(n,id->>'subject',id->>'payer',1,true);END IF;END LOOP;
 FOR g IN SELECT value FROM jsonb_array_elements(q->'grants') LOOP INSERT INTO c1_private.grants SELECT n,g->>'store',g->>'subject',email_key,a,1,true FROM c1_private.identities CROSS JOIN unnest(ARRAY['catalog','redeem','payout']) a WHERE ns=n AND subject=g->>'subject';END LOOP;
 FOR t IN SELECT value FROM jsonb_array_elements(coalesce(q->'terms','[]')) LOOP PERFORM c1_private.windows(t->'windows');INSERT INTO c1_private.terms VALUES(n,t->>'store',t->>'meal',(t->>'version')::bigint,decode(t->>'body','base64'),decode(t->>'image','base64'),c1_private.h(t->>'body_digest'),c1_private.h(t->>'image_digest'),c1_private.h(t->>'terms_hash'),c1_private.money(t->'price'),t->'windows',convert_to(t->>'name','UTF8'),convert_to(t->>'description','UTF8'),true);INSERT INTO c1_private.catalog_head VALUES(n,t->>'store',t->>'meal',(t->>'version')::bigint,coalesce((t->>'listed')::boolean,true));END LOOP;
 RETURN jsonb_build_object('initialized',true,'namespace',n);END $$;
CREATE FUNCTION c1_api.fixture_assertion(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE d c1_private.deployment;BEGIN d=c1_private.guard(n);INSERT INTO c1_private.assertions VALUES(n,c1_private.h(q->>'assertion_hash'),q->>'subject',coalesce(q->>'audience','mcpay-c1'),coalesce(q->>'environment','local-synthetic'),d.now+60,false);RETURN jsonb_build_object('expiresAt',d.now+60);END $$;
CREATE FUNCTION c1_api.fixture_clock(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE d c1_private.deployment;t bigint=(q->>'now')::bigint;BEGIN d=c1_private.guard(n);IF t<d.clock_floor THEN UPDATE c1_private.deployment SET halt=true,reason='CLOCK_ROLLBACK' WHERE ns=n;RETURN jsonb_build_object('halted',true);END IF;UPDATE c1_private.deployment SET now=t,clock_floor=t,heartbeat=CASE WHEN coalesce((q->>'heartbeat')::boolean,true) THEN t ELSE heartbeat END WHERE ns=n;RETURN jsonb_build_object('now',t);END $$;
CREATE FUNCTION c1_api.fixture_fault(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ BEGIN PERFORM c1_private.guard(n);IF q->>'kind'='missing_content' THEN UPDATE c1_private.terms SET available=false WHERE ns=n AND store=q->>'store' AND meal=q->>'meal' AND version=(q->>'version')::bigint;ELSIF q->>'kind'='halt' THEN UPDATE c1_private.deployment SET halt=true,reason='TEST_QUARANTINE' WHERE ns=n;ELSE PERFORM c1_private.fail('UNSUPPORTED_FAULT');END IF;RETURN jsonb_build_object('injected',true);END $$;
CREATE FUNCTION c1_api.fixture_snapshot(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ BEGIN RETURN jsonb_build_object('pendingSupport',(SELECT count(*) FROM c1_private.gates WHERE ns=n AND kind='support' AND pending IS NOT NULL),'credentialState',(SELECT coalesce(jsonb_agg(jsonb_build_object('voucher',v.id,'accessEpoch',v.access_epoch,'displayEpoch',v.display_epoch,'issuedAt',v.issued_at,'expiresAt',v.expires_at,'activeAccess',(SELECT count(*) FROM c1_private.access_credentials WHERE ns=n AND voucher=v.id AND active),'activeDisplay',(SELECT count(*) FROM c1_private.display_credentials WHERE ns=n AND voucher=v.id AND active))),'[]') FROM c1_private.vouchers v WHERE v.ns=n),'receipts',(SELECT count(*) FROM c1_private.receipts WHERE ns=n),'appliedReceipts',(SELECT count(*) FROM c1_private.receipts WHERE ns=n AND applied),'orders',(SELECT count(*) FROM c1_private.orders WHERE ns=n),'units',(SELECT count(*) FROM c1_private.units WHERE ns=n),'intents',(SELECT count(*) FROM c1_private.intents WHERE ns=n),'outbox',(SELECT count(*) FROM c1_private.outbox WHERE ns=n),'reservations',(SELECT count(*) FROM c1_private.units WHERE ns=n AND active_op IS NOT NULL),'pendingEmails',(SELECT count(*) FROM c1_private.gates WHERE ns=n AND kind='email' AND pending IS NOT NULL),'pendingSubjects',(SELECT count(*) FROM c1_private.gates WHERE ns=n AND kind='subject_issue' AND pending IS NOT NULL),'vouchers',(SELECT count(*) FROM c1_private.vouchers WHERE ns=n),'entries',(SELECT count(*) FROM c1_private.financial_entries WHERE ns=n),'rollups',(SELECT jsonb_object_agg(store,totals) FROM c1_private.rollups WHERE ns=n),'intentStates',(SELECT coalesce(jsonb_object_agg(id,stage),'{}') FROM c1_private.intents WHERE ns=n),'provenance',c1_private.provenance(n));END $$;
